b_marital_status = observation(entity='Alice', entity_source='s10', predicate='married', predicate_source='s2')
b_legally_separated = observation(entity='Alice', entity_source='s10', predicate='legally separated under a decree of divorce or of separate maintenance', predicate_source='s3')
b_taxable_year = observation(entity='Alice', entity_source='s11', predicate='year 2018', predicate_source='s11')
b_spouse_death = observation(entity='Alice', entity_source='s10', predicate='spouse dies during his taxable year', predicate_source='s2')
b_determination_time = observation(entity='Alice', entity_source='s11', predicate='determination as of the close of his taxable year', predicate_source='s2')
b_spouse_not_home = observation(entity='Alice', entity_source='s10', predicate='spouse is not a member of such household', predicate_source='s8')
b_home_principal = observation(entity='Alice', entity_source='s10', predicate='maintains as his home a household which constitutes for more than one-half of the taxable year the principal place of abode of a child', predicate_source='s6')
b_cost_furnish = observation(entity='Alice', entity_source='s10', predicate='furnishes over one-half of the cost of maintaining such household during the taxable year', predicate_source='s7')
b_last_six_months = observation(entity='Alice', entity_source='s11', predicate='last 6 months of the taxable year', predicate_source='s8')
b_child_deduction = observation(entity='Alice', entity_source='s10', predicate='entitled to a deduction for the taxable year under section 151', predicate_source='s6')
b_married_status = residual(source='s2', quote='the determination of whether an individual is married shall be made as of the close of his taxable year')
b_legally_separated_status = residual(source='s3', quote='an individual legally separated from his spouse under a decree of divorce or of separate maintenance shall not be considered as married')
b_married_during_year = residual(source='s2', quote='if his spouse dies during his taxable year such determination shall be made as of the time of such death')
b_spouse_death_determination = residual(source='s2', quote='such determination shall be made as of the time of such death')
b_married_individual = residual(source='s6', quote='an individual who is married (within the meaning of subsection (a)) and who files a separate return')
b_household_principal = residual(source='s6', quote='maintains as his home a household which constitutes for more than one-half of the taxable year the principal place of abode of a child')
b_household_cost = residual(source='s7', quote='furnishes over one-half of the cost of maintaining such household during the taxable year')
b_spouse_not_home_during_period = residual(source='s8', quote='during the last 6 months of the taxable year, such individual\'s spouse is not a member of such household')
b_child_deduction_eligibility = residual(source='s6', quote='entitled to a deduction for the taxable year under section 151')
@scope('s0') 
def marital_status_scope(): 
    return True 
@scope('s1') 
def general_rule_scope(): 
    return marital_status_scope 
@scope('s2') 
def marital_status_determination_scope(): 
    return general_rule_scope 
@scope('s3') 
def legally_separated_scope(): 
    return general_rule_scope 
@scope('s4') 
def married_individual_living_apart_scope(): 
    return general_rule_scope 
@scope('s5') 
def married_individual_living_apart_conditions_scope(): 
    return married_individual_living_apart_scope 
@scope('s6') 
def household_principal_condition_scope(): 
    return married_individual_living_apart_conditions_scope 
@scope('s7') 
def household_cost_condition_scope(): 
    return married_individual_living_apart_conditions_scope 
@scope('s8') 
def spouse_not_home_during_period_condition_scope(): 
    return married_individual_living_apart_conditions_scope 
@scope('s9') 
def married_individual_living_apart_conclusion_scope(): 
    return married_individual_living_apart_conditions_scope 
@rule('s2', otherwise=False) 
def marital_status_determination(): 
    return (marital_status_determination_scope and (b_married_status or b_spouse_death_determination)) 
@rule('s3', otherwise=False) 
def legally_separated_status(): 
    return (legally_separated_scope and b_legally_separated) 
@rule('s6', otherwise=False) 
def household_principal_condition(): 
    return (household_principal_condition_scope and b_household_principal) 
@rule('s7', otherwise=False) 
def household_cost_condition(): 
    return (household_cost_condition_scope and b_household_cost) 
@rule('s8', otherwise=False) 
def spouse_not_home_during_period_condition(): 
    return (spouse_not_home_during_period_condition_scope and b_spouse_not_home) 
@rule('s9', otherwise=False) 
def married_individual_living_apart_conclusion(): 
    return (married_individual_living_apart_conclusion_scope and (b_household_principal_condition and b_household_cost_condition and b_spouse_not_home_during_period_condition)) 
query = ('Entailment' if married_individual_living_apart_conclusion else 'Contradiction')
